import java.util.PriorityQueue;

class Solution {
    public int[] mergeKArrays(int[][] matrix, int K) {
        record Cell(int val, int row, int col) {}
        PriorityQueue<Cell> pq = new PriorityQueue<>((a, b) -> a.val - b.val);
        int total = 0;
        for (int r = 0; r < K; ++r) { pq.offer(new Cell(matrix[r][0], r, 0)); total += matrix[r].length; }
        int[] merged = new int[total];
        int idx = 0;
        while (!pq.isEmpty()) {
            Cell cur = pq.poll();
            merged[idx++] = cur.val;
            if (cur.col + 1 < matrix[cur.row].length)
                pq.offer(new Cell(matrix[cur.row][cur.col + 1], cur.row, cur.col + 1));
        }
        return merged;
    }
}
